const Search={index:null,async buildIndex(){this.index={customers:[],appointments:[],orders:[]};const t=await DB.db.customers.toArray();this.index.customers=t.map(t=>({id:t.id,type:"customer",title:`${t.firstName} ${t.lastName}`,subtitle:t.address?`${t.address.line1}, ${t.address.postcodeFormatted}`:"",phone:t.phone,customerNumber:t.customerNumber,keywords:[t.firstName,t.lastName,t.phone,t.email,t.customerNumber,t.address?.line1,t.address?.postcode,t.address?.city].filter(Boolean).join(" ").toLowerCase()}));const e=await DB.db.appointments.toArray();this.index.appointments=e.map(t=>({id:t.id,type:"appointment",title:`${Utils.formatDate(t.date,"short")} ${Utils.formatTime(t.date)}`,subtitle:t.type,keywords:[t.type,t.status,t.outcome,Utils.formatDate(t.date)].filter(Boolean).join(" ").toLowerCase()}));const s=await DB.db.orders.toArray();this.index.orders=s.map(t=>({id:t.id,type:"order",title:t.orderNumber,subtitle:t.supplierOrderNumber||"",keywords:[t.orderNumber,t.supplierOrderNumber,t.status].filter(Boolean).join(" ").toLowerCase()}))},async search(t,e={}){if(!t||t.trim().length<2)return[];const s=t.toLowerCase().trim(),r=[];if(!e.types||e.types.includes("customer"))try{const t=await DB.searchCustomers(s);r.push(...t.map(t=>({type:"customer",id:t.id,title:`${t.firstName} ${t.lastName}`,subtitle:t.customerNumber,detail:t.address?`${t.address.line1}${t.address.postcode?", "+t.address.postcode:""}`:"",icon:"person",data:t})))}catch(t){console.error("Customer search failed:",t)}if(!e.types||e.types.includes("appointment"))try{const t=new Set(r.filter(t=>"customer"===t.type).map(t=>t.id)),e=await DB.db.appointments.filter(e=>t.has(e.customerId)||e.notes&&e.notes.toLowerCase().includes(s)).limit(10).toArray(),a=[...new Set(e.map(t=>t.customerId))],o=new Map;if(a.length){const t=await DB.db.customers.bulkGet?await DB.db.customers.bulkGet(a):await Promise.all(a.map(t=>DB.db.customers.get(t)));for(const e of t)e&&o.set(e.id,e)}for(const t of e){const e=o.get(t.customerId);r.push({type:"appointment",id:t.id,title:`${Utils.formatDate(t.date,"short")} — ${Utils.formatTime(t.date)}`,subtitle:e?`${e.firstName} ${e.lastName}`:"Unknown",detail:CONFIG.appointmentTypes.find(e=>e.id===t.type)?.name||t.type,icon:"event",data:t})}}catch(t){console.error("Appointment search failed:",t)}if(!e.types||e.types.includes("order"))try{const t=await DB.db.orders.filter(t=>(t.orderNumber||"").toLowerCase().startsWith(s)||(t.supplierOrderNumber||"").toLowerCase().startsWith(s)).limit(10).toArray(),e=[...new Set(t.map(t=>t.customerId))],a=new Map;if(e.length){const t=await DB.db.customers.bulkGet?await DB.db.customers.bulkGet(e):await Promise.all(e.map(t=>DB.db.customers.get(t)));for(const e of t)e&&a.set(e.id,e)}for(const e of t){const t=a.get(e.customerId);r.push({type:"order",id:e.id,title:e.orderNumber,subtitle:t?`${t.firstName} ${t.lastName}`:"Unknown",detail:`£${e.total}`,icon:"receipt",data:e})}}catch(t){console.error("Order search failed:",t)}return r.slice(0,e.limit||20)},async searchByPostcode(t){const e=Utils.normalizePostcode(t);return await DB.db.customers.where("postcodeNormalized").startsWith(e).limit(20).toArray()},searchNearby:async(t,e,s=10)=>(await DB.db.customers.toArray()).filter(r=>{if(!r.address?.latLng)return!1;return Geo.calculateDistance(t,e,r.address.latLng[0],r.address.latLng[1])<=s}).map(s=>({...s,distance:Geo.calculateDistance(t,e,s.address.latLng[0],s.address.latLng[1])})).sort((t,e)=>t.distance-e.distance)};